query discoverGrade($gradeID: ID!) {
  discoverGrade(gradeID: $gradeID) {
    id
    name
    type
    season {
      id
      name
      competition {
        id
        name
        organisation {
          ...OrganisationDetails
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  tenantConfiguration {
    label
    statistics {
      enabled
      __typename
    }
    ...TenantContactRolesConfiguration
    gradeTypes {
      value
      isAllPlay
      features {
        hasRounds
        hasSeasonStats
        hasCareerStats
        hasGameStats
        hasFixture
        hasLadder
        __typename
      }
      __typename
    }
    __typename
  }
}

